size_t acpi_thermal_rapl_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void acpi_thermal_rapl_init(void) {
    g_ready = true;
    kprintf("[ARCH/RAPL-THERM] Intel RAPL Power Capping + Core i7-2600K DTS Thermal Sensor + C1E/C6 Governor (%lu rules)\n", (unsigned long)acpi_thermal_rapl_db_size());
}

bool acpi_thermal_rapl_selftest(void) {
    return g_ready && acpi_thermal_rapl_db_size() >= 3520;
}
